#define int long long
using namespace std;
struct node{
	int x,y;
};
int a[55],b[55];
signed main(){
	int n;
	cin>>n;
	int sn=0,sm=0;
	for(int i=1;i<=n;i++){
		cin>>a[i];
		sn+=a[i];
	}
	int m;
	cin>>m;
	for(int i=1;i<=m;i++){
		cin>>b[i]; 
		sm+=b[i];
	}
	int ans=0;
	for(int i=1;i<=n;i++){
		if(sn*(n-1)<n*(sn-a[i])*n&&sn*(n-1)<n*(sn-a[i])&&sm*(m+1)<m*(sm+a[i])*m&&sm*(m+1)<m*(sm+a[i])&&n>=2){
			ans++;
		}
		if(sn*(n+1)<n*(sn+b[i])*n&&sn*(n+1)<n*(sn+b[i])&&sm*(m+1)<m*(sm+b[i])*m&&sm*(m+1)<m*(sm+b[i])&&m>=2){
			ans++;
		}
	}
	cout<<ans;
	return 0;
}
